// JSON string escaping matching canonicaljson's encoder (ensure_ascii=False):
// escape '"' and '\\' always, use shorthand escapes for \b \t \n \f \r,
// other control characters (< 0x20) as \u00XX, everything else kept as-is.

const SHORTHAND_ESCAPES = {
  0x08: "\\b",
  0x09: "\\t",
  0x0a: "\\n",
  0x0c: "\\f",
  0x0d: "\\r",
};

export function escapeJsonString(value) {
  let out = '"';
  for (const ch of value) {
    const code = ch.codePointAt(0);
    if (ch === '"') {
      out += '\\"';
    } else if (ch === "\\") {
      out += "\\\\";
    } else if (Object.prototype.hasOwnProperty.call(SHORTHAND_ESCAPES, code)) {
      out += SHORTHAND_ESCAPES[code];
    } else if (code < 0x20) {
      out += "\\u" + code.toString(16).padStart(4, "0");
    } else {
      out += ch;
    }
  }
  return out + '"';
}

// Compare two strings the way Python's str comparison does: by Unicode
// code point (JS's default relational comparison uses UTF-16 code units,
// which differs for characters outside the BMP).

export function comparePyStr(a, b) {
  const ai = a[Symbol.iterator]();
  const bi = b[Symbol.iterator]();
  while (true) {
    const an = ai.next();
    const bn = bi.next();
    if (an.done && bn.done) return 0;
    if (an.done) return -1;
    if (bn.done) return 1;
    const ac = an.value.codePointAt(0);
    const bc = bn.value.codePointAt(0);
    if (ac !== bc) return ac - bc;
  }
}

export function sortedPy(array) {
  return [...array].sort(comparePyStr);
}

// Reproduce Python's repr() of a bytes object: b'...' with \t \n \r
// shorthands, \\ for backslash, \xNN (lowercase) for non-printable bytes,
// and double-quote delimiters only when the data contains "'" but not '"'.

function isPrintableAscii(byte) {
  return byte >= 0x20 && byte < 0x7f;
}

export function pyBytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // "'"
  const hasDouble = bytes.includes(0x22); // '"'
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = "b" + quoteChar;
  for (const byte of bytes) {
    if (byte === 0x5c) {
      out += "\\\\";
    } else if (byte === quote) {
      out += "\\" + quoteChar;
    } else if (byte === 0x09) {
      out += "\\t";
    } else if (byte === 0x0a) {
      out += "\\n";
    } else if (byte === 0x0d) {
      out += "\\r";
    } else if (isPrintableAscii(byte)) {
      out += String.fromCharCode(byte);
    } else {
      out += "\\x" + byte.toString(16).padStart(2, "0");
    }
  }
  return out + quoteChar;
}

// Reimplementation of canonicaljson.encode_canonical_json based on its
// observable behavior: most compact separators ("," and ":"), dict keys
// sorted by Unicode code point, ensure_ascii=False output, and the result
// encoded to UTF-8 bytes.

import { escapeJsonString } from "./jsonStringEscape.mjs";
import { comparePyStr } from "./pyCompare.mjs";

function encodeValue(value) {
  if (value === null) return "null";
  if (value === true) return "true";
  if (value === false) return "false";
  if (typeof value === "string") return escapeJsonString(value);
  if (Array.isArray(value)) {
    return "[" + value.map(encodeValue).join(",") + "]";
  }
  if (typeof value === "object") {
    const keys = Object.keys(value).sort(comparePyStr);
    const items = keys.map(
      (key) => escapeJsonString(key) + ":" + encodeValue(value[key])
    );
    return "{" + items.join(",") + "}";
  }
  if (typeof value === "number") {
    return String(value);
  }
  throw new TypeError("Object of type " + typeof value + " is not JSON serializable");
}

export function encodeCanonicalJson(value) {
  return new TextEncoder().encode(encodeValue(value));
}

// Minimal reimplementation of the argparse behavior of the source script:
// two required string options --a and --b, -h/--help, "--opt value" and
// "--opt=value" forms, "expected one argument" when a value looks like an
// option, last occurrence wins, unrecognized arguments reported, errors to
// stderr with exit code 2.

import { basename } from "node:path";

const USAGE_ARGS = "[-h] --a A --b B";

function getProg() {
  return basename(process.argv[1] || "test7.mjs");
}

function printUsage(stream) {
  stream.write(`usage: ${getProg()} ${USAGE_ARGS}\n`);
}

function fail(message) {
  printUsage(process.stderr);
  process.stderr.write(`${getProg()}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  printUsage(process.stdout);
  process.stdout.write(
    `\noptions:\n` +
      `  -h, --help  show this help message and exit\n` +
      `  --a A\n` +
      `  --b B\n`
  );
  process.exit(0);
}

function looksLikeOption(token) {
  return token.length > 1 && token.startsWith("-");
}

export function parseArgs(argv) {
  const values = {};
  const extras = [];
  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    if (token === "-h" || token === "--help") {
      printHelp();
    } else if (token === "--a" || token === "--b") {
      const name = token.slice(2);
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        fail(`argument ${token}: expected one argument`);
      }
      values[name] = next;
      i += 2;
    } else if (token.startsWith("--a=") || token.startsWith("--b=")) {
      const eq = token.indexOf("=");
      values[token.slice(2, eq)] = token.slice(eq + 1);
      i += 1;
    } else {
      extras.push(token);
      i += 1;
    }
  }

  const missing = [];
  if (values.a === undefined) missing.push("--a");
  if (values.b === undefined) missing.push("--b");
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(", ")}`);
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(" ")}`);
  }
  return values;
}

#!/usr/bin/env node
import { parseArgs } from "./lib/argParser.mjs";
import { encodeCanonicalJson } from "./lib/canonicalJson.mjs";
import { sortedPy } from "./lib/pyCompare.mjs";
import { pyBytesRepr } from "./lib/pyBytesRepr.mjs";

function main() {
  const args = parseArgs(process.argv.slice(2));

  const data = [args.a, args.b];
  const result1 = encodeCanonicalJson(data); // Encode list as canonical JSON
  const result2 = encodeCanonicalJson(sortedPy(data)); // Encode sorted list as canonical JSON
  console.log(pyBytesRepr(result1));
  console.log(pyBytesRepr(result2));
}

main();
